pub enum ConfigSetLocationValue {
    /// User config (`~/.config/aube/config.toml` for known aube settings, `~/.npmrc` for registry/auth and unknown keys)
    #[value(name = "user")]
    User,
    /// `<cwd>/.npmrc`
    #[value(name = "project")]
    Project,
    /// Alias for `user` — aube has no separate global config file.
    #[value(name = "global")]
    Global,
}

