/// Alias for `config get` (hidden; prefer `config get`)
#[derive(Args)]
#[usage(effect = "read")]
pub struct GetArgs {
    /// Emit the value as JSON.
    ///
    /// Matches `pnpm config get --json`: a missing key renders as `undefined`, a found value is JSON-encoded.
    #[usage(long = "json")]
    pub json: bool,
    /// Shortcut for `--location project`.
    #[usage(long = "local", conflicts = "--location")]
    pub local: bool,
    /// Which config location(s) to read.
    ///
    /// Defaults to `merged` — the last-write-wins view of user aube config, `~/.npmrc`, then `./.npmrc`, matching what install actually sees. Use `user` or `project` to restrict the lookup.
    #[usage(
        long = "location",
        value_name = "LOCATION",
        value_enum,
        default = "merged"
    )]
    pub location: ::std::option::Option<GetLocationValue>,
    /// The setting key.
    ///
    /// Accepts either a pnpm canonical name (e.g. `autoInstallPeers`) or an `.npmrc` alias (e.g. `auto-install-peers`).
    #[usage(arg, name = "KEY")]
    pub key: ::std::string::String,
}

#[derive(ValueEnum)]
pub enum GetLocationValue {
    /// Merge `~/.npmrc`, user aube config, and project `.npmrc`, last-write-wins (same precedence install uses).
    #[value(name = "merged")]
    Merged,
    /// Only user config (`~/.config/aube/config.toml` + `~/.npmrc`)
    #[value(name = "user")]
    User,
    /// Only `<cwd>/.npmrc`
    #[value(name = "project")]
    Project,
    /// Alias for `user`.
    #[value(name = "global")]
    Global,
}

