#[usage(effect = "write")]
pub struct LinkArgs {
    /// Register into (or resolve from) the global link registry.
    ///
    /// The registry lives at `$XDG_CACHE_HOME/aube/global-links`, `$HOME/.cache/aube/global-links` when `XDG_CACHE_HOME` is unset, or `%LOCALAPPDATA%\aube\global-links` on Windows. Default behavior for bare `aube link` / `aube link <name>` — the flag exists for pnpm parity and makes the intent explicit.
    #[usage(long = "global", short = 'g')]
    pub global: bool,
    /// Package name, or path to a local directory
    #[usage(arg, name = "PACKAGE")]
    pub package: ::std::option::Option<::std::string::String>,
}

/// Print the resolved dependency tree
#[derive(Args)]
#[usage(
    after_long_help = "Examples:\n\n  $ aube list\n  my-app@1.0.0 /home/user/project\n\n  dependencies:\n  ├── express 4.19.2\n  ├── lodash 4.17.21\n  └── zod 3.23.8\n\n  devDependencies:\n  ├── typescript 5.4.5\n  └── vitest 1.6.0\n\n  # Show the full transitive tree\n  $ aube list --depth Infinity\n  my-app@1.0.0 /home/user/project\n\n  dependencies:\n  ├─┬ express 4.19.2\n  │ ├── accepts 1.3.8\n  │ ├── body-parser 1.20.2\n  │ └── ...\n\n  # Only direct production deps\n  $ aube list --prod\n\n  # Machine-readable: one path per line (real store locations)\n  $ aube list --parseable\n  /home/user/project\n  /home/user/project/node_modules/.aube/express@4.19.2/node_modules/express\n  /home/user/project/node_modules/.aube/lodash@4.17.21/node_modules/lodash\n\n  # Filter to a single package\n  $ aube list express\n",
    effect = "read"
)]
pub struct ListArgs {
    /// Show only devDependencies
    #[usage(long = "dev", short = 'D', conflicts = "--prod")]
    pub dev: bool,
    /// List globally-installed packages instead of the project's dependency tree
    #[usage(long = "global", short = 'g')]
    pub global: bool,
    /// Show only production dependencies (skip devDependencies)
    #[usage(long = "prod", long = "production", short = 'P', conflicts = "--dev")]
    pub prod: bool,
    /// How deep to render the transitive tree.
    ///
    /// `0` (default) shows only the top-level direct deps. Pass `9999` (or any large number) for the full graph; `--depth=Infinity` is accepted for pnpm/npm compat. `--depth=-1` (pnpm spelling) lists project headers only — no direct or transitive deps.
    #[usage(long = "depth", value_name = "DEPTH", default = "0")]
    pub depth: ::std::option::Option<::std::string::String>,
    /// Output format: one of `default`, `json`, or `parseable`
    #[usage(
        long = "format",
        value_name = "FORMAT",
        value_enum,
        default = "default"
    )]
    pub format: ::std::option::Option<ListFormatValue>,
    /// Shortcut for `--format json`.
    ///
    /// Emit a JSON array of package entries.
    #[usage(long = "json", conflicts = "--format")]
    pub json: bool,
    /// List packages from the lockfile only, without checking node_modules.
    #[usage(long = "lockfile-only")]
    pub lockfile_only: bool,
    /// Show version and path for each entry.
    ///
    /// Default output is already name + version; `--long` adds the store path for debugging.
    #[usage(long = "long")]
    pub long: bool,
    /// Shortcut for `--format parseable`.
    ///
    /// Emit one tab-separated line per package.
    #[usage(long = "parseable", conflicts("--format", "--json"))]
    pub parseable: bool,
    /// Optional package name (or glob-like prefix match) to filter the output
    #[usage(arg, name = "PATTERN")]
    pub pattern: ::std::option::Option<::std::string::String>,
}

#[derive(ValueEnum)]
pub enum ListFormatValue {
    #[value(name = "default")]
    Default,
    #[value(name = "json")]
    Json,
    #[value(name = "parseable")]
    Parseable,
}

