#[derive(Args)]
#[usage(
    after_long_help = "Examples:\n\n  $ aube peers check\n  All peer dependencies are satisfied.\n\n  # With issues\n  $ aube peers check\n  1 unmet, 1 missing peer dependencies:\n\n  ├─┬ @emotion/react@11.11.4\n  │ └── ✕ unmet peer react@>=16.8: found 17.0.2\n  └─┬ react-dom@18.2.0\n    └── ✕ missing peer react@^18.0.0\n\n  # Machine-readable\n  $ aube peers check --json\n",
    effect = "read"
)]
pub struct PeersCheckArgs {
    /// Emit a JSON report instead of the human-readable tree.
    #[usage(long = "json")]
    pub json: bool,
}

/// Inspect peer-dependency resolution from the lockfile
#[derive(Args)]
#[usage(effect = "read")]
pub struct PeersArgs {
    #[usage(subcommand)]
    pub command: PeersCommands,
}

#[derive(Subcommands)]
pub enum PeersCommands {
    /// Check for unmet and missing peer-dependency issues by reading the lockfile.
    #[usage(
        name = "check",
        help = "Check for unmet and missing peer-dependency issues by reading the lockfile.",
        long_help = "Check for unmet and missing peer-dependency issues by reading the\nlockfile.\n\nExits with status 1 if any issue is reported."
    )]
    Check(Box<PeersCheckArgs>),
}

