/// Show the store path.
#[derive(Args)]
#[usage(effect = "read")]
pub struct StorePathArgs {}

/// Remove unreferenced packages from the global store.
///
/// Operates on the store printed by `aube store path`; it does not touch project node_modules directories, manifests, or lockfiles.
///
/// It removes global virtual-store graph entries not referenced by any registered project. Entries from older aube releases live outside the registry-managed versioned namespace and are not touched. It then prunes content-store files.
///
/// On reflink filesystems such as APFS or btrfs, link counts cannot prove project reachability, so content-store pruning relies on cached package indexes. Global virtual-store reachability comes from project links.
#[derive(Args)]
#[usage(effect = "write")]
pub struct StorePruneArgs {
    /// Do not actually delete anything; report what would be pruned.
    #[usage(long = "dry-run")]
    pub dry_run: bool,
    /// Emit the dry-run plan as one machine-readable JSON document.
    #[usage(long = "json", requires = "--dry-run")]
    pub json: bool,
}

/// Verify the store against cached package indexes.
///
/// Confirms every file referenced by a cached package index is still present in the store and that its BLAKE3 hash matches. Exits non-zero when any corruption is detected.
#[derive(Args)]
#[usage(effect = "read")]
pub struct StoreStatusArgs {}

/// Manage the global store
#[derive(Args)]
#[usage(effect = "read")]
pub struct StoreArgs {
    #[usage(subcommand)]
    pub command: StoreCommands,
}

#[derive(Subcommands)]
pub enum StoreCommands {
    /// Add one or more packages to the global store without linking them into any project.
    #[usage(
        name = "add",
        help = "Add one or more packages to the global store without linking them into any project.",
        long_help = "Add one or more packages to the global store without linking them\ninto any project.\n\nEach argument is a package spec: `lodash`, `lodash@4.17.21`,\n`react@next`, or `express@^4`."
    )]
    Add(Box<StoreAddArgs>),
    /// Show the store path.
    #[usage(name = "path")]
    Path(Box<StorePathArgs>),
    /// Remove unreferenced packages from the global store.
    #[usage(name = "prune")]
    Prune(Box<StorePruneArgs>),
    /// Verify the store against cached package indexes.
    #[usage(name = "status")]
    Status(Box<StoreStatusArgs>),
}

