/// Print reverse dependency chains explaining why a package is installed
#[derive(Args)]
#[usage(
    after_long_help = "Examples:\n\n  $ aube why debug\n  my-app@1.0.0 /home/user/project\n\n  dependencies:\n  express 4.19.2\n  └── debug 2.6.9\n  body-parser 1.20.2\n  └── debug 2.6.9\n\n  # Only follow chains starting at a devDependency\n  $ aube why --dev typescript\n\n  # Include each node's store path\n  $ aube why --long debug\n\n  # Tab-separated, one chain per line (pipe-friendly)\n  $ aube why --parseable debug\n\n  # JSON: an array of chain objects\n  $ aube why --json debug\n",
    effect = "read"
)]
pub struct WhyArgs {
    /// Only follow chains that start at a devDependency
    #[usage(long = "dev", short = 'D', conflicts = "--prod")]
    pub dev: bool,
    /// Only follow chains that start at a production (or optional) dependency
    #[usage(long = "prod", long = "production", short = 'P', conflicts = "--dev")]
    pub prod: bool,
    /// Output as JSON — an array of chain objects
    #[usage(long = "json", conflicts = "--parseable")]
    pub json: bool,
    /// Append each node's `.aube/<dep_path>` store path to the tree output
    #[usage(long = "long")]
    pub long: bool,
    /// Tab-separated output: one line per chain, `importer\tdep_type\tname@ver\t...`
    #[usage(long = "parseable")]
    pub parseable: bool,
    /// Package name to search for (exact match against package names)
    #[usage(arg, name = "PACKAGE")]
    pub package: ::std::string::String,
}

/// A fast Node.js package manager
#[derive(Cli)]
#[usage(bin = "aube", name = "aube")]
pub struct Cli {
    /// Change to directory before running (like `make -C` or `mise --cd`)
    #[usage(
        long = "dir",
        long = "cd",
        long = "prefix",
        short = 'C',
        global,
        value_name = "DIR"
    )]
    pub dir: ::std::option::Option<::std::string::String>,
    /// Scope command execution to workspace packages matching PATTERN.
    ///
    /// Supports exact names (`my-pkg`), globs (`@scope/*`, `*-plugin`), paths (`./packages/api`), graph selectors (`pkg...`, `...pkg`), git-ref selectors (`[origin/main]`), and exclusions (`!pkg`). Repeatable; matches are OR-ed.
    ///
    /// Currently honored by `run`, `test`, `start`, `stop`, `restart`, `install`, `exec`, `list`, `publish`, `deploy`, `add`, `remove`, `update`, `why`, and implicit-script invocations.
    #[usage(long = "filter", short = 'F', global, value_name = "WORKSPACE", var)]
    pub filter: ::std::vec::Vec<::std::string::String>,
    /// Run the command across every workspace package.
    ///
    /// Equivalent to `--filter=*`; if `--filter` is also given, `--recursive` is a no-op and the explicit filter wins. Honored by the same commands as `--filter`.
    #[usage(long = "recursive", short = 'r', global)]
    pub recursive: bool,
    /// Enable verbose/debug logging (shortcut for `--loglevel debug`)
    #[usage(long = "verbose", short = 'v', global)]
    pub verbose: bool,
    /// Print version and check for updates.
    ///
    /// Manual flag so we can run the async update notifier alongside the version print — clap's auto `Action::Version` exits inside `parse_from`, before the tokio runtime is built.
    #[usage(long = "version", short = 'V', global)]
    pub version: bool,
    /// Group workspace command output after each package finishes.
    ///
    /// Accepted for pnpm compatibility; aube's workspace fanout is currently sequential, so output is already grouped.
    #[usage(long = "aggregate-output", global, hide, conflicts = "--stream")]
    pub aggregate_output: bool,
    /// Force colored output even when stderr is not a TTY.
    ///
    /// Overrides `NO_COLOR` / `CLICOLOR=0`. Mutually exclusive with `--no-color`.
    #[usage(long = "color", global, conflicts = "--no-color")]
    pub color: bool,
    #[usage(
        help = "Enable cold-install deep diagnostics. Modes:   summary  — sum_ms / mean / max / %wall table at end   trace    — summary + critical path + starvation + what-if + lifecycle   live     — like trace, plus print every span >= 100ms to stderr live   full     — like trace, plus write JSONL trace to a file (defaults to ./aube-diag.jsonl)",
        long_help = "Enable cold-install deep diagnostics. Modes:\n  summary  — sum_ms / mean / max / %wall table at end\n  trace    — summary + critical path + starvation + what-if + lifecycle\n  live     — like trace, plus print every span >= 100ms to stderr live\n  full     — like trace, plus write JSONL trace to a file (defaults to ./aube-diag.jsonl)\n\nQuick form: `--diag` with no value defaults to `trace`.\nOutput file path can be set via `--diag-file`. Threshold for live\nmode via `--diag-threshold-ms`.",
        long = "diag",
        global,
        value_optional,
        default_missing = "trace",
        value_name = "MODE"
    )]
    pub diag: ::std::option::Option<::std::string::String>,
    /// Path for `--diag full` JSONL trace (default: ./aube-diag.jsonl)
    #[usage(long = "diag-file", global, value_name = "PATH")]
    pub diag_file: ::std::option::Option<::std::string::String>,
    /// Live-mode threshold: only print spans whose duration is >= N ms (default 100).
    #[usage(long = "diag-threshold-ms", global, value_name = "MS")]
    pub diag_threshold_ms: ::std::option::Option<::std::string::String>,
    /// Error when a workspace selector matches no packages.
    ///
    /// Accepted globally; selected commands already fail on empty matches.
    #[usage(long = "fail-if-no-match", global)]
    pub fail_if_no_match: bool,
    /// Production-only variant of `--filter`.
    ///
    /// Same selector grammar as `--filter`, but graph walks (`pkg...`, `...pkg`) only follow `dependencies` / `optionalDependencies` / `peerDependencies` edges — `devDependencies` (and packages reachable solely through them) are skipped. Non-graph forms (exact name, glob, path, `[git-ref]`) behave identically to `--filter`. Repeatable; can be combined with `--filter`.
    #[usage(long = "filter-prod", global, value_name = "PATTERN", var)]
    pub filter_prod: ::std::vec::Vec<::std::string::String>,
    /// Ignore workspace discovery for commands that support workspace fanout.
    ///
    /// Parsed for pnpm compatibility.
    #[usage(long = "ignore-workspace", global, hide)]
    pub ignore_workspace: bool,
    /// Include the workspace root in recursive workspace operations.
    ///
    /// Parsed for pnpm compatibility.
    #[usage(long = "include-workspace-root", global, hide)]
    pub include_workspace_root: bool,
    /// Set the log level. Logs at or above this level are shown.
    #[usage(long = "loglevel", global, value_name = "LEVEL", value_enum)]
    pub loglevel: ::std::option::Option<LoglevelValue>,
    /// Disable colored output.
    ///
    /// Overrides `FORCE_COLOR` / `CLICOLOR_FORCE` and sets `NO_COLOR=1` so downstream libraries (miette, clx, child processes) all see the same choice.
    #[usage(long = "no-color", global)]
    pub no_color: bool,
    /// Output format: default, append-only, ndjson, silent.
    ///
    /// `default` renders the progress UI when stderr is a TTY; `append-only` disables the progress UI in favor of plain line-at-a-time logs; `ndjson` swaps the tracing fmt layer for the JSON formatter (one JSON object per log event on stderr) and is what tooling wrappers should consume; `silent` suppresses all non-error output (alias for `--loglevel silent`).
    #[usage(long = "reporter", global, value_name = "NAME", value_enum)]
    pub reporter: ::std::option::Option<ReporterValue>,
    /// Suppress all non-error output (alias for `--loglevel silent`)
    #[usage(long = "silent", global)]
    pub silent: bool,
    /// Stream workspace command output as each child process writes it.
    ///
    /// Accepted for pnpm compatibility; aube's workspace fanout is currently sequential.
    #[usage(long = "stream", global, hide, conflicts = "--aggregate-output")]
    pub stream: bool,
    /// Route lifecycle and workspace command output through stderr.
    ///
    /// Accepted for pnpm compatibility.
    #[usage(long = "use-stderr", global, hide)]
    pub use_stderr: bool,
    /// Prefer workspace packages when resolving dependencies.
    ///
    /// Parsed for pnpm compatibility; aube already resolves workspace packages when a workspace is present.
    #[usage(long = "workspace-packages", global, hide)]
    pub workspace_packages: bool,
    /// Run from the workspace root regardless of the current package.
    #[usage(long = "workspace-root", global)]
    pub workspace_root: bool,
    /// Automatically answer yes to prompts.
    ///
    /// Parsed for pnpm compatibility; aube does not currently prompt on these paths.
    #[usage(long = "yes", short = 'y', global, hide)]
    pub yes: bool,
    #[usage(subcommand)]
    pub command: ::std::option::Option<Commands>,
}

#[derive(ValueEnum)]
pub enum LoglevelValue {
    #[value(name = "trace")]
    Trace,
    #[value(name = "debug")]
    Debug,
    #[value(name = "info")]
    Info,
    #[value(name = "warn")]
    Warn,
    #[value(name = "error")]
    Error,
    #[value(name = "silent")]
    Silent,
}

#[derive(ValueEnum)]
pub enum ReporterValue {
    #[value(name = "default")]
    Default,
    #[value(name = "append-only")]
    AppendOnly,
    #[value(name = "ndjson")]
    Ndjson,
    #[value(name = "silent")]
    Silent,
}

#[derive(Subcommands)]
pub enum Commands {
    /// Bootstrap aube's cached node-gyp and print the executable path.
    #[usage(name = "__node-gyp-bootstrap", hide)]
    NodeGypBootstrap(Box<NodeGypBootstrapArgs>),
    /// Manage package access and visibility on the registry
    #[usage(name = "access")]
    Access(Box<AccessArgs>),
    /// Emit shell activation code for runtime tool shims
    #[usage(name = "activate")]
    Activate(Box<ActivateArgs>),
    /// Add a dependency
    #[usage(name = "add", alias = "a")]
    Add(Box<AddArgs>),
    /// Approve ignored dependency build scripts.
    #[usage(name = "approve-builds")]
    ApproveBuilds(Box<ApproveBuildsArgs>),
    /// Check installed packages against the registry advisory DB
    #[usage(name = "audit")]
    Audit(Box<AuditArgs>),
    /// Print the path to `node_modules/.bin`
    #[usage(name = "bin")]
    Bin(Box<BinArgs>),
    /// Open package bug tracker URLs
    #[usage(name = "bugs", alias = "issues")]
    Bugs(Box<BugsArgs>),
    /// Inspect and manage the packument metadata cache
    #[usage(name = "cache")]
    Cache(Box<CacheArgs>),
    /// Print a file from the global store by integrity or hex hash
    #[usage(name = "cat-file")]
    CatFile(Box<CatFileArgs>),
    /// Print the cached package index JSON for `<name>@<version>`
    #[usage(name = "cat-index")]
    CatIndex(Box<CatIndexArgs>),
    /// Verify installed packages can resolve their declared deps.
    #[usage(name = "check")]
    Check(Box<CheckArgs>),
    /// Clean install: delete node_modules, then install with frozen lockfile.
    #[usage(name = "ci", alias("clean-install", "ic", "install-clean"))]
    Ci(Box<CiArgs>),
    /// Remove `node_modules` across every workspace project.
    #[usage(name = "clean")]
    Clean(Box<CleanArgs>),
    /// Generate shell completions (bash, zsh, fish)
    #[usage(name = "completion")]
    Completion(Box<CompletionArgs>),
    /// Read and write settings in `.npmrc`
    #[usage(name = "config", alias = "c")]
    Config(Box<ConfigArgs>),
    /// Scaffold a project from a `create-*` starter kit (via dlx)
    #[usage(name = "create")]
    Create(Box<CreateArgs>),
    /// Re-resolve the lockfile to collapse duplicate versions
    #[usage(name = "dedupe")]
    Dedupe(Box<DedupeArgs>),
    /// Deploy a workspace package into a target directory with deps inlined
    #[usage(name = "deploy")]
    Deploy(Box<DeployArgs>),
    /// Mark published versions of a package as deprecated on the registry
    #[usage(name = "deprecate")]
    Deprecate(Box<DeprecateArgs>),
    /// Report deprecated packages in the resolved dependency graph
    #[usage(name = "deprecations")]
    Deprecations(Box<DeprecationsArgs>),
    /// Diagnostic trace analysis (compare/analyze JSONL traces)
    #[usage(name = "diag")]
    Diag(Box<DiagArgs>),
    /// Manage package distribution tags on the registry
    #[usage(name = "dist-tag", alias = "dist-tags")]
    DistTag(Box<DistTagArgs>),
    /// Fetch a package into a throwaway environment and run its binary
    #[usage(name = "dlx")]
    Dlx(Box<DlxArgs>),
    /// Run broad install-health diagnostics
    #[usage(name = "doctor")]
    Doctor(Box<DoctorArgs>),
    /// Execute a locally installed binary
    #[usage(name = "exec", alias = "x")]
    Exec(Box<ExecArgs>),
    /// Download lockfile dependencies into the store without linking node_modules
    #[usage(name = "fetch")]
    Fetch(Box<FetchArgs>),
    /// List packages whose cached index references a given file hash
    #[usage(name = "find-hash")]
    FindHash(Box<FindHashArgs>),
    /// Alias for `config get` (hidden; prefer `config get`)
    #[usage(name = "get", hide)]
    Get(Box<GetArgs>),
    /// Print packages whose install scripts were skipped by `pnpm.allowBuilds`
    #[usage(name = "ignored-builds")]
    IgnoredBuilds(Box<IgnoredBuildsArgs>),
    /// Convert a supported lockfile into aube-lock.yaml
    #[usage(name = "import")]
    Import(Box<ImportArgs>),
    /// Create a `package.json` in the current directory
    #[usage(name = "init")]
    Init(Box<InitArgs>),
    /// Install all dependencies
    #[usage(name = "install", alias = "i")]
    Install(Box<InstallArgs>),
    /// Install dependencies, then run the `test` script (pnpm compat alias).
    #[usage(name = "install-test", hide, alias = "it")]
    InstallTest(Box<InstallTestArgs>),
    /// Alias for `list --long` (hidden; prefer `list --long`)
    #[usage(name = "la", hide)]
    La(Box<LaArgs>),
    /// Report the licenses of installed dependencies
    #[usage(name = "licenses")]
    Licenses(Box<LicensesArgs>),
    /// Link a local package globally, or into the current project
    #[usage(name = "link", alias = "ln")]
    Link(Box<LinkArgs>),
    /// Print the resolved dependency tree
    #[usage(name = "list", alias = "ls")]
    List(Box<ListArgs>),
    /// Alias for `list --long` (hidden; prefer `list --long`)
    #[usage(name = "ll", hide)]
    Ll(Box<LlArgs>),
    /// Store a registry auth token in the user's ~/.npmrc
    #[usage(name = "login", alias = "adduser")]
    Login(Box<LoginArgs>),
    /// Remove a registry auth token from the user's ~/.npmrc
    #[usage(name = "logout")]
    Logout(Box<LogoutArgs>),
    /// Run Node.js through aube's project runtime resolver
    #[usage(name = "node")]
    Node(Box<NodeArgs>),
    /// Report dependencies whose installed version lags behind the registry
    #[usage(name = "outdated")]
    Outdated(Box<OutdatedArgs>),
    /// Manage package owners (not implemented — use `npm owner`)
    #[usage(name = "owner", hide)]
    Owner(Box<OwnerArgs>),
    /// Create a publishable `.tgz` tarball from the current project
    #[usage(name = "pack")]
    Pack(Box<PackArgs>),
    /// Extract a package into an edit directory so it can be patched
    #[usage(name = "patch")]
    Patch(Box<PatchArgs>),
    /// Generate a `.patch` file from a `aube patch` edit directory
    #[usage(name = "patch-commit")]
    PatchCommit(Box<PatchCommitArgs>),
    /// Remove patch entries from `pnpm.patchedDependencies`
    #[usage(name = "patch-remove")]
    PatchRemove(Box<PatchRemoveArgs>),
    /// Inspect peer-dependency resolution from the lockfile
    #[usage(name = "peers")]
    Peers(Box<PeersArgs>),
    /// Manage package.json entries (not implemented — use `npm pkg`)
    #[usage(name = "pkg", hide)]
    Pkg(Box<PkgArgs>),
    /// Print the current package prefix directory
    #[usage(name = "prefix")]
    Prefix(Box<PrefixArgs>),
    /// Remove extraneous packages from project `node_modules`.
    #[usage(name = "prune")]
    Prune(Box<PruneArgs>),
    /// Publish the current package to the registry
    #[usage(name = "publish")]
    Publish(Box<PublishArgs>),
    /// Alias for `clean` — remove `node_modules` across every workspace project.
    #[usage(name = "purge")]
    Purge(Box<PurgeArgs>),
    /// Query packages in the resolved dependency graph
    #[usage(name = "query")]
    Query(Box<QueryArgs>),
    /// Re-run root lifecycle scripts and allowlisted dependency builds
    #[usage(
        name = "rebuild",
        help = "Re-run root lifecycle scripts and allowlisted dependency builds",
        long_help = "`aube rebuild [<pkg>...]` — without args, re-run the root package's\npreinstall hook, then install / postinstall work for dependency\npackages allowed by the active `allowBuilds` /\n`onlyBuiltDependencies` policy, then the root package's install /\npostinstall / prepare lifecycle hooks.\n\nWith one or more package names, run lifecycle scripts only for the\nnamed deps and skip the root hooks. Match is by graph `name`, which\nis the in-tree alias when one is configured (so `aube rebuild\nmy-alias` works for a manifest entry like\n`\"my-alias\": \"npm:real-pkg@1.0\"`, matching pnpm).\n\nUnlike the other lifecycle shortcuts, `rebuild` intentionally does not\nauto-install: `aube install` already runs these same four hooks after\nlinking, so triggering an install here would double-run every script\non a stale tree. Users who actually want a fresh install should run\n`aube install`.",
        alias = "rb"
    )]
    Rebuild(Box<RebuildArgs>),
    /// Run a supported command across workspace packages
    #[usage(name = "recursive", alias("multi", "m"))]
    Recursive(Box<RecursiveArgs>),
    /// Remove a dependency
    #[usage(name = "remove", alias("rm", "uninstall", "un", "uni"))]
    Remove(Box<RemoveArgs>),
    /// Restart a package (shortcut for `run restart`; falls back to `stop` + `start`)
    #[usage(name = "restart")]
    Restart(Box<RestartArgs>),
    /// Print the path to `node_modules`
    #[usage(name = "root")]
    Root(Box<RootArgs>),
    /// Run a script defined in package.json
    #[usage(name = "run", alias = "run-script")]
    Run(Box<RunArgs>),
    /// Manage the project's Node.js runtime (pin, install, inspect)
    #[usage(name = "runtime", alias = "rt")]
    Runtime(Box<RuntimeArgs>),
    /// Generate a Software Bill of Materials (CycloneDX or SPDX)
    #[usage(name = "sbom")]
    Sbom(Box<SbomArgs>),
    /// Search the registry for packages (not implemented — use `npm search`)
    #[usage(name = "search", hide)]
    Search(Box<SearchArgs>),
    /// Alias for `config set` (hidden; prefer `config set`)
    #[usage(name = "set", hide)]
    Set(Box<SetArgs>),
    /// Set a `package.json` script (not implemented — use `npm set-script`)
    #[usage(name = "set-script", hide)]
    SetScript(Box<SetScriptArgs>),
    /// Show the companies sponsoring aube and the jdx.dev open source tools
    #[usage(name = "sponsors")]
    Sponsors(Box<SponsorsArgs>),
    /// Stage packages for publishing (not implemented — use `npm stage`)
    #[usage(name = "stage")]
    Stage(Box<StageArgs>),
    /// Start a package (shortcut for `run start`)
    #[usage(name = "start")]
    Start(Box<StartArgs>),
    /// Stop a package (shortcut for `run stop`)
    #[usage(name = "stop")]
    Stop(Box<StopArgs>),
    /// Manage the global store
    #[usage(name = "store")]
    Store(Box<StoreArgs>),
    /// Run the `test` script (shortcut for `run test`)
    #[usage(name = "test", alias = "t")]
    Test(Box<TestArgs>),
    /// Manage registry auth tokens (not implemented — use `npm token`)
    #[usage(name = "token", hide)]
    Token(Box<TokenArgs>),
    /// Inspect npm package publishing trust
    #[usage(name = "trust")]
    Trust(Box<TrustArgs>),
    /// Clear an existing deprecation on the registry
    #[usage(name = "undeprecate")]
    Undeprecate(Box<UndeprecateArgs>),
    /// Unlink a package (remove linked entries from node_modules)
    #[usage(name = "unlink", alias = "dislink")]
    Unlink(Box<UnlinkArgs>),
    /// Remove a package (or a single version) from the registry
    #[usage(name = "unpublish")]
    Unpublish(Box<UnpublishArgs>),
    /// Update dependencies
    #[usage(name = "update", alias("up", "upgrade"))]
    Update(Box<UpdateArgs>),
    /// Bump the version in package.json (and optionally create a git commit + tag)
    #[usage(name = "version")]
    Version(Box<VersionArgs>),
    /// Print package metadata from the registry
    #[usage(name = "view", alias("info", "show", "v"))]
    View(Box<ViewArgs>),
    /// Report the current registry user (not implemented — use `npm whoami`)
    #[usage(name = "whoami", hide)]
    Whoami(Box<WhoamiArgs>),
    /// Print reverse dependency chains explaining why a package is installed
    #[usage(name = "why", alias = "w")]
    Why(Box<WhyArgs>),
}
